param([string]$Directory)
$ErrorActionPreference='Stop'
foreach($source in @('windows-dns-credential-recovery.ps1','windows-recovery-envelope.ps1','windows-recovery-channel.ps1')){. (Join-Path $Directory $source)}
$fixture=Get-Content -LiteralPath (Join-Path $Directory 'fixtures.json') -Raw|ConvertFrom-Json
$channel=Join-Path $Directory 'channel';$bridge=Join-Path $Directory 'bridge';$script:writes=0;$script:secretAllowed=$true;$script:quiescent=$true;$script:lost=$false;$script:candidateAccepted=$true;$script:crash=$false
$ast=[Management.Automation.Language.Parser]::ParseFile((Join-Path $Directory 'windows-dns-credential-recovery.ps1'),[ref]$null,[ref]$null);$writer=$ast.Find({param($node);$node -is [Management.Automation.Language.FunctionDefinitionAst] -and $node.Name -eq 'Write-DnsRecoveryFile'},$true);Invoke-Expression ($writer.Extent.Text.Replace('function Write-DnsRecoveryFile','function Write-OriginalDnsRecoveryFile'))
function Write-DnsRecoveryFile([string]$Path,[byte[]]$Bytes){if([IO.Path]::GetFileName($Path) -eq 'kubeconfig.json'){$script:writes++};Write-OriginalDnsRecoveryFile $Path $Bytes;if($script:crash -and [IO.Path]::GetFileName($Path) -eq 'channel-current-request.json'){$script:crash=$false;throw 'Injected crash after durable request intent'}}
function Assert($value,[string]$reason){if(!$value){throw $reason}}
function Reject([scriptblock]$work,[string]$reason){$denied=$false;try{$null=& $work}catch{$denied=$true};Assert $denied $reason}
$authenticate={param($path,$uid);if([IO.Path]::GetFileName($path).StartsWith('candidate-') -and !$script:candidateAccepted){return $false};if($script:lost -and [IO.Path]::GetFileName($path) -eq 'kubeconfig.json'){$script:lost=$false;throw 'Readback loss'};return $uid -ceq $fixture.accountUid -and (Get-Content -LiteralPath $path -Raw|ConvertFrom-Json).users[0].user.token -ceq 'synthetic.restored.signature'}
function Request([string]$Name,[int64]$Now=10000){return Invoke-DnsRecoveryChannelRequest -ChannelRoot $channel -BridgeRoot $bridge -Envelope $fixture.cases.$Name.envelope -ClusterUid $fixture.clusterUid -AccountUid $fixture.accountUid -ClusterCaData 'Synthetic-Pinned-CA' -AssertQuiescent {$script:quiescent} -Authenticate $authenticate -AssertSecretTarget {param($id,$payload);return $script:secretAllowed -and $payload.accountUid -ceq $fixture.accountUid} -Now $Now}
$checks=@()
$prepared=Request 'prepare';Assert ($prepared.status -eq 'Succeeded' -and $prepared.transactionStatus -eq 'Prepared' -and (Test-Path -LiteralPath (Join-Path $bridge 'credential-recovery-active.json'))) 'Encrypted channel preparation did not acquire its lease';Assert ((Request 'prepare' 11000).status -eq 'Succeeded') 'Known acknowledgement could not be recovered after expiry';Assert ($script:writes -eq 0) 'Preparation wrote the credential';$checks+='Encrypted prepare and durable expired duplicate acknowledgement'
$script:secretAllowed=$false;Assert ((Request 'secretDenied').status -eq 'Interrupted') 'Commit adopted an unconfirmed cluster Secret';Assert ($script:writes -eq 0) 'Rejected Secret readback wrote credentials';$script:secretAllowed=$true;$checks+='Cluster Secret mismatch prevents local mutation'
$script:lost=$true;Assert ((Request 'lostCommit').status -eq 'Interrupted') 'Lost authentication reply was not interrupted';Assert ($script:writes -eq 1) 'Expected one candidate-confirmed credential write';$stamp=(Get-Item -LiteralPath (Join-Path $bridge 'kubeconfig.json')).LastWriteTimeUtc.Ticks
. (Join-Path $Directory 'windows-recovery-channel.ps1');Assert ((Request 'lostCommit' 11000).status -eq 'Interrupted') 'Restart replayed an uncertain commit';Assert ((Request 'reconcile').transactionStatus -eq 'Applied') 'Independent readback did not reconcile';Assert ($script:writes -eq 1 -and (Get-Item -LiteralPath (Join-Path $bridge 'kubeconfig.json')).LastWriteTimeUtc.Ticks -eq $stamp) 'Reconciliation rewrote a confirmed credential';Assert (!(Test-Path -LiteralPath (Join-Path $bridge 'credential-recovery-active.json'))) 'Confirmed recovery retained its lease';$checks+='Commit reply loss, restart and read-only reconciliation without replay'
Assert ((Request 'status').transactionStatus -eq 'Applied') 'Status is not bound to the original transaction';Reject {Request 'foreignOwner'} 'Another caller reused a transaction';$checks+='Status and owner binding'
$script:quiescent=$false;Assert ((Request 'quiescentDenied').status -eq 'Interrupted') 'Active jobs were accepted';Assert (!(Test-Path -LiteralPath (Join-Path $bridge 'credential-recovery-active.json'))) 'Rejected preparation leaked a lease';$script:quiescent=$true;$checks+='Active DNS work blocks preparation'
$handle=Open-DnsRecoveryLock $channel 'recovery-agent.lock';try{Reject {Request 'agentBusy'} 'A second agent bypassed the process lock'}finally{$handle.Dispose()};$handle=Open-DnsRecoveryLock $bridge 'bridge-mutation.lock';try{Reject {Request 'bridgeBusy'} 'Recovery raced a DNS operation'}finally{$handle.Dispose()};$checks+='Exclusive agent and DNS operation locks'
$script:crash=$true;Reject {Request 'crashBeforePrepare'} 'Injected durable-intent crash was not observed';Assert ((Request 'crashBeforePrepare' 11000).status -eq 'Interrupted') 'An uncertain request was executed after restart';Assert ($script:writes -eq 1) 'Interrupted prepare changed credentials';$checks+='Durable request intent survives a crash without action replay'
# Test the bridge entry points from the actual source while replacing DNS work.
$bridgeAst=[Management.Automation.Language.Parser]::ParseFile((Join-Path $Directory 'windows-dns-bridge.ps1'),[ref]$null,[ref]$null);foreach($name in @('Run-Bridge','Process-Job')){$definition=$bridgeAst.Find({param($node);$node -is [Management.Automation.Language.FunctionDefinitionAst] -and $node.Name -eq $name},$true);Invoke-Expression $definition.Extent.Text}
$ConfigurationPath=Join-Path $bridge 'configuration.json';$script:iterations=0;function Invoke-BridgeIteration {$script:iterations++};Run-Bridge;Assert ($script:iterations -eq 1) 'Unlocked bridge iteration did not run'
$lease=Join-Path $bridge 'credential-recovery-active.json';[IO.File]::WriteAllText($lease,'{"id":"synthetic-lease"}');try{Run-Bridge;Assert ($script:iterations -eq 1) 'Recovery lease did not pause the bridge';Reject {Process-Job ([pscustomobject]@{id='synthetic-job'})} 'Direct job entry bypassed the recovery lease'}finally{[IO.File]::Delete($lease)}
$handle=Open-DnsRecoveryLock $bridge 'bridge-mutation.lock';try{Reject {Run-Bridge} 'Bridge bypassed the shared recovery lock'}finally{$handle.Dispose()};$checks+='Actual bridge entry points pause queued DNS writes and honor shared lock'
# A separate PowerShell 5.1 process holds the same Windows file lock.
$ready=Join-Path $bridge 'lock-ready';$job=Start-Job -ArgumentList $bridge,$ready -ScriptBlock {param($root,$ready);$h=[IO.File]::Open((Join-Path $root 'bridge-mutation.lock'),[IO.FileMode]::OpenOrCreate,[IO.FileAccess]::ReadWrite,[IO.FileShare]::None);try{[IO.File]::WriteAllText($ready,'ready');Start-Sleep -Seconds 20}finally{$h.Dispose()}}
try{for($i=0;$i -lt 100 -and !(Test-Path -LiteralPath $ready);$i++){Start-Sleep -Milliseconds 100};Assert (Test-Path -LiteralPath $ready) 'Independent process did not hold lock';Reject {Open-DnsRecoveryLock $bridge 'bridge-mutation.lock'} 'Independent process lock was bypassed'}finally{Stop-Job $job;Remove-Job $job};$checks+='Independent PowerShell process serialization'
Assert ((Request 'candidateRejected').transactionStatus -eq 'Prepared') 'Candidate fixture preparation failed';$script:candidateAccepted=$false;Assert ((Request 'candidateRetry').status -eq 'Interrupted') 'Bad candidate authenticated';Assert ($script:writes -eq 1) 'Candidate authentication failure rewrote credentials';$checks+='Candidate API authentication failure prevents file replacement'
$json=Get-ChildItem -LiteralPath $channel -Filter '*.json'|ForEach-Object {[IO.File]::ReadAllText($_.FullName)};Assert (!(($json -join '').Contains('synthetic.restored.signature'))) 'A channel receipt leaked plaintext';Assert (!(($json -join '').Contains('Synthetic-Pinned-CA'))) 'A channel receipt leaked configuration';$checks+='Sanitized durable channel receipts'
@{passed=$true;checks=$checks;credentialWrites=$script:writes;productionWrites=0}|ConvertTo-Json -Depth 8
